    @Test("gpReadStringByteLength caps consumption at field width")
    func gpReadStringByteLengthCapsConsumptionAtFieldWidth() async throws {
        let sentinelByte: Double = 202.0
        let fieldSize: Double = 21.0
        let overlongHint: Double = 32.0
        let raw: Uint8Array = Uint8Array(fieldSize + 2.0)
        raw[0] = (overlongHint)
        do {
            var i: Double = 0.0
            while i < fieldSize {
                raw[(i + 1.0).toInt()] = 65.0
                i += 1
            }
        }
        raw[(fieldSize + 1.0).toInt()] = (sentinelByte)
        let buffer: ByteBuffer = ByteBuffer.fromBuffer((raw as! Uint8Array))
        let result: String = try GpBinaryHelpers.gpReadStringByteLength(buffer, (fieldSize), "utf-8")
        TestGlobals.expect(result).toBe("A".`repeat`((fieldSize)))
        TestGlobals.expect(buffer.position).toBe(1.0 + fieldSize)
        TestGlobals.expect(buffer.readByte()).toBe((sentinelByte))
    }

    @Suite("corrupt")
    final class CorruptSuite {
        private static func corruptTest(_ intToWrite: Double, _ offset: Double, _ expectedOverflowLabel: String) async throws {
            let buffer: Uint8Array = await TestPlatformPartials.loadFile("test-data/corrupt/healthy.gp5")
            buffer[(offset + 0.0).toInt()] = jsAnd(jsShr(intToWrite, 0), 255)
            buffer[(offset + 1.0).toInt()] = jsAnd(jsShr(intToWrite, 8), 255)
            buffer[(offset + 2.0).toInt()] = jsAnd(jsShr(intToWrite, 16), 255)
            buffer[(offset + 3.0).toInt()] = jsAnd(jsShr(intToWrite, 24), 255)
            let importer: Gp3To5Importer = GpImporterTestHelper.prepareImporterWithBytes(buffer, Settings())
            do {
                try importer.readScore()
                throw JsError("Expected readScore to fail with an OverflowError")
            } catch {
                let e = error
                if e is OverflowError {
                    TestGlobals.expect((e as! OverflowError).message).toContain(expectedOverflowLabel)
                    return
                }
                throw e
            }
        }

        @Test("max-bar-count")
        func maxBarCount() async throws {
            try await CorruptSuite.corruptTest(5000.0, 1235.0, "bar count")
        }

        @Test("max-track-count")
        func maxTrackCount() async throws {
            try await CorruptSuite.corruptTest(300.0, 1239.0, "track count")
        }

        @Test("notice-lines-count")
        func noticeLinesCount() async throws {
            try await CorruptSuite.corruptTest(5000.0, 82.0, "notice line count")
        }

        @Test("beat-count")
        func beatCount() async throws {
            try await CorruptSuite.corruptTest(200.0, 1460.0, "beat count")
        }

        @Test("tremolo-count")
        func tremoloCount() async throws {
            try await CorruptSuite.corruptTest(500.0, 1584.0, "tremolo bar point count")
        }

        @Test("bend-count")
        func bendCount() async throws {
            try await CorruptSuite.corruptTest(500.0, 1479.0, "note bend point count")
        }

        @Test("eof")
        func eof() async throws {
            var buffer: Uint8Array = await TestPlatformPartials.loadFile("test-data/corrupt/healthy.gp5")
            buffer = buffer.slice(0.0, buffer.length / 2.0)
            let importer: Gp3To5Importer = GpImporterTestHelper.prepareImporterWithBytes(buffer, Settings())
            try TestGlobals.expect({ () -> Score in
                return try importer.readScore()
            }).toThrow(EndOfReaderError.self)
        }

        init() {}
    }

    @Test("harmonic-types")
    func harmonicTypes() async throws {
        let reader: Gp3To5Importer = await GpImporterTestHelper.prepareImporterWithFile("guitarpro5/harmonic-types.gp5")
        let score: Score = try reader.readScore()
        let b0: Beat = try score.tracks.jsElement(0).staves.jsElement(0).bars.jsElement(0).voices.jsElement(0).beats[0]
        try TestGlobals.expect(b0.notes.jsElement(0).harmonicType).toBe(HarmonicType.Natural)
        try TestGlobals.expect(b0.notes.jsElement(0).harmonicValue).toBe(12.0)
        let b1: Beat = try score.tracks.jsElement(0).staves.jsElement(0).bars.jsElement(0).voices.jsElement(0).beats[1]
        try TestGlobals.expect(b1.notes.jsElement(0).harmonicType).toBe(HarmonicType.Artificial)
        try TestGlobals.expect(b1.notes.jsElement(0).harmonicValue).toBe(17.0)
        let b2: Beat = try score.tracks.jsElement(0).staves.jsElement(0).bars.jsElement(0).voices.jsElement(0).beats[2]
