        let b3: Beat = try score.tracks.jsElement(0).staves.jsElement(0).bars.jsElement(0).voices.jsElement(0).beats[3]
        try TestGlobals.expect(b3.notes.jsElement(0).harmonicType).toBe(HarmonicType.Pinch)
